function addLog(message, tone = '') { const item = document.createElement('div'); item.className = `log-line ${tone}`; item.innerHTML = `<span class="log-time">${new Date().toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' })}</span><span>${escapeHtml(message)}</span>`; logEl.appendChild(item); while (logEl.childElementCount > 240) logEl.firstElementChild?.remove(); requestAnimationFrame(() => { logEl.scrollTop = logEl.scrollHeight; }); }
