  element.innerHTML = `<div class="account-manager"><button class="account-current" id="accountMenuBtn" aria-expanded="false">${avatarMarkup(account, 'avatar signed account-profile-avatar')}<span><strong>${escapeHtml(account.username)}</strong><small>${accounts.length} gespeicherte${accounts.length === 1 ? 's' : ''} Konto${accounts.length === 1 ? '' : 'en'}</small></span><b>⌄</b></button><div class="account-menu" id="accountMenu" hidden><p class="account-menu-label">MINECRAFT-KONTEN</p>${accountRows}${avatarTools}<button class="account-add" id="addAccountBtn">+ Konto hinzufügen</button></div></div>`;
  $('accountMenuBtn').onclick = () => { const menu = $('accountMenu'); const open = menu.hidden; menu.hidden = !open; $('accountMenuBtn').setAttribute('aria-expanded', String(open)); };
