async function selectSavedAccount(id) { const result = await window.vortex.selectAccount(id); if (!result.ok) { addLog(result.error || 'Konto konnte nicht gewechselt werden.', 'error'); return; } launcherState.account = result.account; launcherState.accounts = result.accounts; setAccount(result.account, result.accounts); addLog(`Aktives Konto: ${result.account.username}`, 'success'); }
