function currentSummary() { return launcherState?.versions?.find(instance => instance.version === selectedVersion); }
function cosmeticsSummary() { return launcherState?.versions?.find(instance => instance.version === launcherState?.cosmeticsVersion); }
function updatePlaySummary() { const summary = currentSummary(); $('selectedVersionLabel').textContent = selectedVersion; $('coreStatus').textContent = summary?.ready ? 'Aktiv' : 'Bereitstellen'; $('modCount').textContent = summary ? `${summary.totalModCount} Mods` : '— Mods'; }
