  updateOfficialServerHero(servers.find(server => server.official));
  list.innerHTML = servers.map(server => { const details = serverStatusDetails(server.status); return `<article class="server-card gallery${server.id === selectedId ? ' selected' : ''}${server.official ? ' official' : ''}">${serverImageMarkup(server)}<div class="server-card-content"><div class="server-card-heading"><div><div class="server-title-line"><h4>${escapeHtml(server.name)}</h4>${server.official ? '<span class="server-official-label">OFFIZIELL</span>' : ''}</div><code>${escapeHtml(server.address)}</code></div>${server.id === selectedId ? '<span class="server-selected-dot">STANDARD</span>' : ''}</div><p>${escapeHtml(details.description)}</p><small class="server-live-meta ${details.state}">${escapeHtml(details.meta)}</small><div class="server-card-actions"><button class="button small" data-server-join="${escapeAttr(server.id)}"${joinDisabled}>Beitreten</button><button class="server-select-button${server.id === selectedId ? ' selected' : ''}" data-server-select="${escapeAttr(server.id)}">${server.id === selectedId ? '✓ Ausgewählt' : 'Auswählen'}</button><button class="server-refresh-button" data-server-refresh="${escapeAttr(server.id)}" title="Echte Serverdaten aktualisieren" aria-label="${escapeAttr(server.name)} aktualisieren">↻</button>${server.official ? '<span class="server-lock" title="Offizieller Server">⌘</span>' : `<button class="server-remove-button" data-server-remove="${escapeAttr(server.id)}" title="Server entfernen" aria-label="${escapeAttr(server.name)} entfernen">×</button>`}</div></div></article>`; }).join('') || '<p class="mod-empty">Noch keine Server gespeichert.</p>';
