async function removeServer(id) { const server = (launcherState?.servers || []).find(item => item.id === id); if (!server || !confirm(`${server.name} aus deiner Server-Bibliothek entfernen?`)) return; const result = await window.vortex.removeServer(id); if (!result.ok) { addLog(result.error || 'Server konnte nicht entfernt werden.', 'error'); return; } launcherState.servers = result.servers; launcherState.state = result.state; renderServers(); addLog(`${server.name} wurde aus deiner Server-Bibliothek entfernt.`); }
