function renderInstanceCards() { $('instancesGrid').innerHTML = launcherState.versions.map(instance => { const active = instance.version === selectedVersion ? ' selected' : ''; const state = instance.ready && instance.fabricInstalled ? 'Geschützt' : 'Wird automatisch repariert'; const cosmeticLine = instance.cosmeticsSupported ? `<div class="instance-stat accent"><span>COSMETICS</span><strong>${instance.cosmeticProfile?.generatedSkin ? 'Aktiv' : 'Bereit'}</strong></div>` : '<div class="instance-stat"><span>COSMETICS</span><strong>1.21.11</strong></div>'; return `<article class="instance-card${active}"><div class="instance-title"><div><h3>${instance.version}</h3><p>FABRIC + VORTEX CLIENT</p></div><span class="instance-state">${state}</span></div><div class="instance-stats"><div class="instance-stat"><span>PFLICHTMODS</span><strong>${instance.coreModCount}</strong></div><div class="instance-stat"><span>GESAMT</span><strong>${instance.totalModCount} Mods</strong></div>${cosmeticLine}</div><div class="instance-actions"><button class="button secondary" data-select="${instance.version}">Auswählen</button><button class="button secondary" data-instance-folder="${instance.version}">Instanzen-Ordner</button><button class="button ghost" data-mods="${instance.version}">Mods</button></div></article>`; }).join(''); document.querySelectorAll('[data-select]').forEach(button => button.onclick = async () => { selectedVersion = button.dataset.select; await window.vortex.selectVersion(selectedVersion); $('versionSelect').value = selectedVersion; updatePlaySummary(); renderInstanceCards(); modScopeLabel(); await refreshInstalled(); await renderOverview(); showPage('play'); }); document.querySelectorAll('[data-instance-folder]').forEach(button => button.onclick = () => window.vortex.openInstanceFolder(button.dataset.instanceFolder)); document.querySelectorAll('[data-mods]').forEach(button => button.onclick = () => window.vortex.openModsFolder(button.dataset.mods)); }
