function updateUpdateView(update = launcherState?.update || {}) {
  const modal = $('updateModal');
  const sidebarUpdate = $('sidebarUpdate');
  const active = ['available', 'downloading', 'downloaded'].includes(update.status);
  const version = update.availableVersion || '';
  sidebarUpdate.hidden = !active;
  if (active) $('sidebarUpdateText').textContent = update.status === 'downloaded' ? `Version ${version} bereit · Neustart` : `Version ${version} verfügbar`;
  if (!active || !version) { if (modal) modal.hidden = true; return; }
  if (deferredUpdateVersion === version && update.status !== 'downloaded') return;
  showUpdatePopup(update);
}
function showUpdatePopup(update = launcherState?.update || {}) {
  const modal = $('updateModal'); if (!modal || !update.availableVersion) return;
  const downloading = update.status === 'downloading';
  const downloaded = update.status === 'downloaded';
  const progress = Math.max(0, Math.min(100, update.progress || 0));
  $('updateModalTitle').textContent = downloaded ? 'Neustart erforderlich' : downloading ? 'Update wird geladen' : 'Update verfügbar';
  $('updateModalText').textContent = downloaded ? `Version ${update.availableVersion} ist bereit. Starte den Launcher neu, um sie zu installieren.` : downloading ? `Version ${update.availableVersion} wird sicher heruntergeladen.` : `Version ${update.availableVersion} ist verfügbar und hält deinen Launcher aktuell.`;
  $('updateModalNote').textContent = downloaded ? 'Der Launcher wird kurz neu gestartet. Deine Instanzen, Mods, Cosmetics und Einstellungen bleiben erhalten.' : 'Beim Abschluss der Aktualisierung wird der Launcher automatisch neu gestartet. Deine Instanzen und Dateien bleiben erhalten.';
  $('updateModalProgress').hidden = !downloading;
  $('updateModalProgressValue').textContent = `${progress} %`;
  $('updateModalProgressBar').style.width = `${progress}%`;
  const action = $('updateActionBtn');
  action.textContent = downloaded ? 'Jetzt neu starten' : downloading ? 'Wird heruntergeladen …' : 'Jetzt aktualisieren';
  action.disabled = downloading;
  $('updateLaterBtn').textContent = downloaded ? 'Später neu starten' : 'Später';
  modal.hidden = false;
}
async function runUpdateAction() {
  const update = launcherState?.update || {};
  if (update.status === 'available') { const result = await window.vortex.downloadUpdate(); if (launcherState) launcherState.update = result; updateUpdateView(result); return; }
  if (update.status === 'downloaded') { const result = await window.vortex.installUpdate(); if (!result.ok) addLog(result.error || 'Update konnte nicht gestartet werden.', 'error'); }
}
