async function refreshAiStudio() { try { updateAiStudio(await window.vortex.getAiState()); } catch (_) { updateAiStudio({ ready: false, encryptionAvailable: false }); } }
function showAiResult(result, type) { const preview = $('aiResultPreview'); const design = result.design || {}; $('aiResultTitle').textContent = design.title || 'KI-Entwurf erstellt'; $('aiResultText').textContent = type === 'mod' ? `Private Projektvorlage ${result.modId || ''} wurde lokal angelegt. Prüfe die Dateien vor einem Build.` : `${design.summary || 'Lokaler Entwurf erstellt.'}${type === 'cape' ? ' Starte Minecraft neu, damit das Cape geladen wird.' : ''}`; if (result.preview) { preview.innerHTML = `<img src="${escapeAttr(result.preview)}" alt="${escapeAttr(design.title || 'KI-Entwurf')}" />`; preview.querySelector('img').onerror = () => { preview.innerHTML = '<span>✺</span>'; }; } else preview.innerHTML = '<span>✦</span>'; }
async function saveAiKey() { const input = $('aiKeyInput'); const button = $('saveAiKeyBtn'); const key = input.value.trim(); const provider = $('aiProvider').value; if (!key) { $('aiKeyState').textContent = 'Gib deinen privaten API-Schlüssel ein.'; return; } button.disabled = true; const result = await window.vortex.saveAiKey(key, provider, $('aiTextModel').value); input.value = ''; button.disabled = false; if (!result.ok) { $('aiKeyState').textContent = result.error || 'Schlüssel konnte nicht gespeichert werden.'; return; } updateAiStudio(result.state); addLog(`${provider === 'manus' ? 'Manus' : 'OpenAI'}-Schlüssel wurde geschützt lokal gespeichert.`, 'success'); }
async function removeAiKey() { if (!aiState?.ready || !confirm('Den lokal gespeicherten KI-Schlüssel entfernen?')) return; const result = await window.vortex.removeAiKey(); if (result.ok) { updateAiStudio(result.state); addLog('Lokaler KI-Schlüssel wurde entfernt.'); } }
async function createAiAsset(kind) { const prompt = $('aiPrompt').value.trim(); if (!prompt) { $('aiCreateStatus').textContent = 'Beschreibe zuerst deinen gewünschten Entwurf.'; return; } const button = $(kind === 'skin' ? 'generateAiSkinBtn' : kind === 'cape' ? 'generateAiCapeBtn' : 'generateAiModBtn'); const label = button.textContent; button.disabled = true; button.textContent = 'KI entwirft …'; $('aiCreateStatus').textContent = 'Dein privater Entwurf wird erstellt …'; const result = kind === 'skin' ? await window.vortex.generateAiSkin(prompt) : kind === 'cape' ? await window.vortex.generateAiCape(prompt) : await window.vortex.createAiModProject(prompt); button.disabled = false; button.textContent = label; if (!result.ok) { $('aiCreateStatus').textContent = result.error || 'KI-Entwurf konnte nicht erstellt werden.'; addLog(result.error || 'KI-Entwurf konnte nicht erstellt werden.', 'error'); return; } showAiResult(result, kind); $('aiCreateStatus').textContent = kind === 'skin' ? 'KI-Skin erstellt und als Vortex-Skin-Variante aktiviert.' : kind === 'cape' ? 'KI-Cape erstellt und für den nächsten Minecraft-Start aktiviert.' : 'Private Mod-Projektvorlage erstellt. Prüfe den Quellcode vor einem Build.'; addLog(`KI-${kind === 'mod' ? 'Modprojekt' : kind} erstellt: ${result.design?.title || 'Entwurf'}.`, 'success'); if (kind === 'skin') { await refresh(); await updateSkinPreview(); } }

async function checkUpdate() { const result = await window.vortex.checkForUpdates(); if (launcherState) launcherState.update = result; updateUpdateView(result); }

// Mod installer — exactly the layout and interaction model from the supplied source ZIP.
function templateIcon(hit) { const letter = escapeHtml((hit.title || '?').slice(0, 1).toUpperCase()); const iconUrl = /^https:\/\/cdn\.modrinth\.com\//i.test(hit.iconUrl || '') ? hit.iconUrl : null; return iconUrl ? `<img class="mod-icon" src="${escapeAttr(iconUrl)}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.replaceWith(Object.assign(document.createElement('span'),{className:'mod-icon fallback',textContent:'${letter}'}))" />` : `<span class="mod-icon fallback">${letter}</span>`; }
function renderModResults(hits) { const box = $('modResults'); if (!hits.length) { box.innerHTML = '<p class="mod-empty">Nothing found. Try another term.</p>'; return; } box.innerHTML = hits.map((hit, index) => { const button = hit.installed ? '<button class="button small" disabled>Already installed</button>' : `<button class="button small" data-install="${index}">Installieren</button>`; return `<article class="mod-card${hit.installed ? ' has-mod' : ''}">${templateIcon(hit)}<div class="mod-body"><strong>${escapeHtml(hit.title)}</strong><p>${escapeHtml(hit.description || '')}</p><small>${Number(hit.downloads || 0).toLocaleString('en-GB')} downloads${hit.author ? ' · ' + escapeHtml(hit.author) : ''}</small></div>${button}</article>`; }).join(''); box.querySelectorAll('[data-install]').forEach(button => button.onclick = () => installTemplateMod(Number(button.dataset.install), button)); }
async function searchTemplateMods() { const query = $('modQuery').value.trim(); if (!query) { setStatus('Enter a search term.'); return; } const button = $('modSearchBtn'); button.disabled = true; $('modResults').innerHTML = '<p class="mod-empty">Searching …</p>'; const result = await window.vortex.searchMods(query, selectedVersion, 0); button.disabled = false; if (!result.ok) { $('modResults').innerHTML = `<p class="mod-empty">${escapeHtml(result.error || 'Search failed.')}</p>`; return; } templateModResults = result.results || []; renderModResults(templateModResults); }
async function installTemplateMod(index, button) { const hit = templateModResults[index]; if (!hit) return; button.disabled = true; const label = button.textContent; button.textContent = 'Downloading …'; addLog(`Installing ${hit.title} for ${selectedVersion} …`); const result = await window.vortex.installModProject(hit.projectId, selectedVersion); if (result.ok) { hit.installed = true; button.textContent = 'Installed'; addLog(`${hit.title}: ${(result.installed || []).length + (result.present || []).length} file(s) in the mods folder.`, 'success'); await refreshInstalled(); await renderOverview(); await refresh(); } else { button.textContent = label; button.disabled = false; addLog(result.error || 'Installation failed.', 'error'); } }
async function refreshInstalled() { const box = $('installedMods'); if (!box || !launcherState) return; const list = await window.vortex.listMods(selectedVersion); if (!list.length) { box.innerHTML = '<p class="mod-empty">No mods in this instance yet.</p>'; return; } box.hidden = installedCollapsed; box.innerHTML = list.map(mod => `<div class="installed-row"><span>${escapeHtml(mod.name)}</span><button class="text-button" data-installed-remove="${escapeAttr(mod.file || mod.name)}">Remove</button></div>`).join(''); box.querySelectorAll('[data-installed-remove]').forEach(button => button.onclick = async () => { const result = await window.vortex.removeMod(selectedVersion, button.dataset.installedRemove); if (!result.ok) addLog(result.error || 'Could not remove this Vortex file.', 'error'); else addLog(`${button.dataset.installedRemove} removed.`, 'success'); await refreshInstalled(); await renderOverview(); }); }

// Installed mods — exact card, totals, switch and remove model from the supplied source ZIP.
function formatSize(bytes) { if (!bytes) return ''; const mb = bytes / 1048576; return mb >= 1 ? `${mb.toFixed(1)} MB` : `${Math.max(1, Math.round(bytes / 1024))} KB`; }
async function renderOverview() { const list = $('overviewList'); const totals = $('overviewTotals'); if (!list || !launcherState) return; list.innerHTML = '<p class="mod-empty">Loading …</p>'; const mods = await window.vortex.listMods(selectedVersion); const active = mods.filter(mod => mod.enabled).length; const own = mods.filter(mod => !mod.required).length; $('ovInstance').textContent = `Minecraft ${selectedVersion}`; totals.innerHTML = `<div class="total-card"><span>${active}</span><small>Active</small></div><div class="total-card"><span>${mods.length - active}</span><small>Disabled</small></div><div class="total-card"><span>${own}</span><small>Added by you</small></div><div class="total-card"><span>${escapeHtml(selectedVersion)}</span><small>Version</small></div>`; if (!mods.length) { list.innerHTML = '<p class="mod-empty">Nothing installed yet. Pick a version above.</p>'; return; } list.innerHTML = mods.map(mod => { const title = mod.title || mod.name.replace(/\.jar$/, ''); const letter = escapeHtml(title.slice(0, 1).toUpperCase()); const source = mod.protected ? '../assets/branding/vortex-logo.png' : (/^https:\/\/cdn\.modrinth\.com\//i.test(mod.iconUrl || '') ? mod.iconUrl : null); const icon = source ? `<img class="mod-icon own" src="${escapeAttr(source)}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.replaceWith(Object.assign(document.createElement('span'),{className:'mod-icon fallback',textContent:'${letter}'}))" />` : `<span class="mod-icon fallback">${letter}</span>`; const origin = mod.protected ? 'Vortex core' : mod.required ? 'Vortex required' : 'Added by you'; const actions = mod.required ? '<span class="ov-lock" title="Belongs to Vortex Client — cannot be disabled or removed">Fixed</span>' : `<button class="mod-switch${mod.enabled ? ' on' : ''}" data-mod="${escapeAttr(mod.file || mod.name)}" aria-label="${mod.enabled ? 'Turn off' : 'Turn on'}"><span></span></button><button class="ov-remove" data-overview-remove="${escapeAttr(mod.file || mod.name)}" title="Remove from this instance" aria-label="Remove">✕</button>`; return `<article class="mod-card ov-card${mod.enabled ? '' : ' off'}">${icon}<div class="mod-body"><strong>${escapeHtml(title)}</strong><p>${escapeHtml(mod.name)}</p><small>${origin}</small></div><div class="ov-actions">${actions}</div></article>`; }).join(''); list.querySelectorAll('[data-overview-remove]').forEach(button => button.onclick = async () => { const name = button.dataset.overviewRemove; if (!confirm(`Remove ${name} from this instance?`)) return; button.disabled = true; const result = await window.vortex.removeMod(selectedVersion, name); addLog(result.ok ? `${name} removed.` : (result.error || `Could not remove ${name}.`), result.ok ? 'success' : 'error'); await renderOverview(); await refreshInstalled(); }); list.querySelectorAll('[data-mod]').forEach(button => button.onclick = async () => { button.disabled = true; const result = await window.vortex.toggleMod(selectedVersion, button.dataset.mod); if (!result.ok) addLog(result.error || 'Could not toggle.', 'error'); else addLog(`${button.dataset.mod.replace(/\.disabled$/, '')} ${result.enabled ? 'enabled' : 'disabled'}.`, 'success'); await renderOverview(); await refreshInstalled(); }); }

// Resource-Pack installer — same card and instance-list interaction model as the Mod installer.
function renderResourcePackResults(hits) { const box = $('resourcePackResults'); if (!hits.length) { box.innerHTML = '<p class="mod-empty">Nothing found. Try another term.</p>'; return; } box.innerHTML = hits.map((pack, index) => { const button = `<button class="button small" data-pack-install="${index}">Installieren</button>`; return `<article class="mod-card">${templateIcon(pack)}<div class="mod-body"><strong>${escapeHtml(pack.title)}</strong><p>${escapeHtml(pack.description || '')}</p><small>${Number(pack.downloads || 0).toLocaleString('en-GB')} downloads · ${escapeHtml(pack.gameVersion || selectedVersion)}</small></div>${button}</article>`; }).join(''); box.querySelectorAll('[data-pack-install]').forEach(button => button.onclick = () => installTemplateResourcePack(Number(button.dataset.packInstall), button)); }
async function searchTemplateResourcePacks() { const query = $('resourcePackQuery').value.trim(); if (!query) { setStatus('Enter a resource-pack search term.'); return; } const button = $('resourcePackSearchBtn'); button.disabled = true; $('resourcePackResults').innerHTML = '<p class="mod-empty">Searching …</p>'; const result = await window.vortex.searchResourcePacks(query, selectedVersion, 0); button.disabled = false; if (!result.ok) { $('resourcePackResults').innerHTML = `<p class="mod-empty">${escapeHtml(result.error || 'Search failed.')}</p>`; return; } resourcePackResults = result.results || []; renderResourcePackResults(resourcePackResults); }
async function installTemplateResourcePack(index, button) { const pack = resourcePackResults[index]; if (!pack) return; button.disabled = true; const label = button.textContent; button.textContent = 'Downloading …'; const result = await window.vortex.downloadResourcePack(selectedVersion, { projectId: pack.projectId, versionId: pack.versionId }); if (result.ok) { button.textContent = 'Installed'; addLog(`${result.fileName} saved in the resourcepacks folder.`, 'success'); await refreshInstalledPacks(); } else { button.textContent = label; button.disabled = false; addLog(result.error || 'Resource-pack installation failed.', 'error'); } }
async function refreshInstalledPacks() { const box = $('installedPacks'); if (!box || !launcherState) return; const list = await window.vortex.listResourcePacks(selectedVersion); box.hidden = installedPacksCollapsed; if (!list.length) { box.innerHTML = '<p class="mod-empty">No resource packs in this instance yet.</p>'; return; } box.innerHTML = list.map(pack => `<div class="installed-row"><span>${escapeHtml(pack.name)}</span><button class="text-button" data-pack-remove="${escapeAttr(pack.file)}">Remove</button></div>`).join(''); box.querySelectorAll('[data-pack-remove]').forEach(button => button.onclick = async () => { const result = await window.vortex.removeResourcePack(selectedVersion, button.dataset.packRemove); if (!result.ok) addLog(result.error || 'Could not remove this resource pack.', 'error'); else addLog(`${button.dataset.packRemove} removed.`, 'success'); await refreshInstalledPacks(); }); }

function relativeCommunityTime(value) { const parsed = new Date(String(value || '').replace(' ', 'T') + (String(value || '').endsWith('Z') ? '' : 'Z')); const days = Math.max(0, Math.floor((Date.now() - parsed.getTime()) / 86400000)); if (!Number.isFinite(days) || days === 0) return 'heute'; if (days === 1) return 'vor 1 Tag'; return `vor ${days} Tagen`; }
function updateCommunityView(community = launcherState?.community || {}) { const account = community.websiteAccount; $('communityAccountTitle').textContent = account ? `Angemeldet als ${account.display_name || account.username}` : 'Community-Login erforderlich'; $('communityAccountText').textContent = account ? 'Du kannst jetzt eigene Presets und Makros direkt in der Vortex Community veröffentlichen.' : 'Melde dich mit deinem bestehenden Vortex-Website-Konto an, um Presets und Makros hochzuladen.'; $('communityLoginBtn').textContent = account ? 'Community erneut öffnen' : 'Community anmelden'; $('communityUploadBtn').disabled = !account; }
async function renderCommunity() { const grid = $('communityPresetGrid'); if (!launcherState?.account) { grid.innerHTML = '<p class="mod-empty">Melde dich zuerst mit deinem Minecraft-Konto im Launcher an.</p>'; return; } grid.innerHTML = '<p class="mod-empty">Community-Beiträge werden geladen …</p>'; const result = await window.vortex.listCommunityPresets(); if (!result.ok) { grid.innerHTML = `<p class="mod-empty">${escapeHtml(result.error || 'Community konnte nicht geladen werden.')}</p>`; return; } if (!result.presets.length) { grid.innerHTML = '<p class="mod-empty">Noch keine öffentlichen Presets oder Makros vorhanden.</p>'; return; } grid.innerHTML = result.presets.map((preset, index) => `<article class="community-preset-card"><div class="community-preset-top"><span class="community-kind ${preset.kind}">${preset.kind === 'macro' ? 'MACRO' : 'PRESET'}</span><span>${relativeCommunityTime(preset.createdAt)}</span></div><h3>${escapeHtml(preset.name)}</h3><p>${escapeHtml(preset.description || 'Keine Beschreibung vorhanden.')}</p><div class="community-preset-meta"><span>${escapeHtml(preset.filename)}</span><span>von ${escapeHtml(preset.username)}</span><span>${Number(preset.downloads || 0).toLocaleString('de-DE')} Downloads</span></div><button class="button small" data-community-download="${index}">Herunterladen</button></article>`).join(''); grid.querySelectorAll('[data-community-download]').forEach(button => button.onclick = async () => { const preset = result.presets[Number(button.dataset.communityDownload)]; button.disabled = true; const download = await window.vortex.downloadCommunityPreset(preset.shareCode, preset.filename); if (download.ok) { button.textContent = 'Gespeichert'; addLog(`${preset.name} wurde im Community-Ordner gespeichert.`, 'success'); } else { button.disabled = false; addLog(download.error || 'Community-Beitrag konnte nicht geladen werden.', 'error'); } }); }
async function openCommunityLogin() { const result = await window.vortex.openCommunityLogin(); if (!result.ok) addLog(result.error || 'Community-Anmeldung konnte nicht geöffnet werden.', 'error'); }
async function uploadCommunityPreset() { if (!launcherState?.community?.websiteAccount) { addLog('Melde dich zuerst in der Community an.', 'error'); return; } const name = window.prompt('Name für dein Preset oder Makro:'); if (name === null) return; const description = window.prompt('Kurze Beschreibung (optional):') || ''; const visibility = window.confirm('Öffentlich in der Community anzeigen?\n\nOK = öffentlich · Abbrechen = nur über Link') ? 'public' : 'unlisted'; const result = await window.vortex.uploadCommunityPreset({ name, description, visibility }); if (result.ok) { addLog(`${result.kind === 'macro' ? 'Makro' : 'Preset'} wurde veröffentlicht.`, 'success'); await renderCommunity(); } else if (!result.canceled) addLog(result.error || 'Community-Beitrag konnte nicht hochgeladen werden.', 'error'); }

function showPage(page) { document.querySelectorAll('.page').forEach(element => element.classList.toggle('active', element.id === page)); document.querySelectorAll('.nav-link').forEach(element => element.classList.toggle('active', element.dataset.page === page)); if (page === 'servers') renderServers(); if (page === 'mods') { modScopeLabel(); refreshInstalled(); } if (page === 'resource-packs') { modScopeLabel(); refreshInstalledPacks(); } if (page === 'community') renderCommunity(); if (page === 'cosmetics') { updateSkinPreview(); renderWebsiteCapes(); } if (page === 'ai-studio') refreshAiStudio(); if (page === 'overview') renderOverview();  }
async function refresh() { launcherState = await window.vortex.getState(); selectedVersion = launcherState.state?.selectedVersion || '1.21.11'; selectedHat = launcherState.state?.hat || 'vortex-cap'; selectedEmblem = launcherState.state?.emblem || 'vortex-crest'; setAccount(launcherState.account, launcherState.accounts); renderVersions(); renderInstanceCards(); updatePlaySummary(); renderServers(); updateCosmetics(); updateUpdateView(launcherState.update); updateReleaseNews(launcherState.news); updateCommunityView(launcherState.community); modScopeLabel(); void refreshAiStudio(); void updateSkinPreview(); await refreshInstalled(); await refreshInstalledPacks(); await renderOverview(); }
async function login() { const button = $('loginBtn') || $('addAccountBtn'); if (button) button.disabled = true; addLog('Microsoft-Anmeldung wird gestartet …'); const result = await window.vortex.login(); if (result.ok) { launcherState.account = result.account; launcherState.accounts = result.accounts; setAccount(result.account, result.accounts); addLog(`Angemeldet als ${result.account.username}`, 'success'); } else { addLog(result.error, 'error'); if (button) button.disabled = false; } }
async function logout() { if (!launcherState?.account) return; await removeSavedAccount(launcherState.account.id); }
async function launch() { $('playBtn').disabled = true; $('playLabel').textContent = 'Startet …'; const result = await window.vortex.launch(selectedVersion); if (!result.ok) { addLog(result.error, 'error'); $('playBtn').disabled = false; $('playLabel').textContent = 'Vortex starten'; } }
async function saveCosmetics(patch) { const result = await window.vortex.setCosmetics({ hat: selectedHat, emblem: selectedEmblem, ...patch }); if (!result.ok) { addLog(result.error || 'Cosmetic konnte nicht gespeichert werden.', 'error'); return; } selectedHat = result.hat; selectedEmblem = result.emblem; updateCosmetics(); addLog(`Cosmetics-Auswahl gespeichert: ${hatNames[selectedHat]} + ${emblemNames[selectedEmblem]}.`, 'success'); }
function addCosmeticPreviewFallbacks() { document.querySelectorAll('.cosmetic-art').forEach(image => image.addEventListener('error', () => { const fallback = document.createElement('span'); fallback.className = 'cosmetic-art-fallback'; fallback.textContent = image.closest('[data-hat]')?.dataset.hat === 'none' || image.closest('[data-emblem]')?.dataset.emblem === 'none' ? '×' : (image.alt || 'V').charAt(0).toUpperCase(); fallback.title = image.alt || 'Cosmetic-Vorschau'; image.replaceWith(fallback); }, { once: true })); }
async function renderWebsiteCapes() { const grid = $('websiteCapeGrid'); if (!grid) return; grid.innerHTML = '<p class="mod-empty">Cape-Freischaltungen werden geladen …</p>'; const result = await window.vortex.getWebsiteCapeCatalogue(); const current = result?.choice?.cape || null; if (!result?.ok) { grid.innerHTML = `<p class="mod-empty">Cape-Freischaltung konnte nicht geladen werden.<br><small>${escapeHtml(result?.error || 'Unbekannter Fehler')}</small></p>`; return; } if (result.needsWebsiteLogin) { grid.innerHTML = '<p class="mod-empty">Melde dich auf der Vortex-Website an. Danach wird dein Vortex Member Cape hier freigeschaltet.</p>'; $('websiteCapeNote').textContent = 'Noch nicht auf der Website angemeldet.'; return; } const capes = [{ id: null, name: 'Kein Website-Cape', description: 'Kein freigeschaltetes Cape anwenden.', preview: null }, ...(result.capes || [])]; grid.innerHTML = capes.map(cape => { const selected = (cape.id || null) === current; const preview = cape.preview ? `<img src="${escapeAttr(cape.preview)}" alt="${escapeAttr(cape.name)} Vorschau" loading="lazy" />` : '<span class="website-cape-fallback">×</span>'; return `<button class="website-cape-card${selected ? ' selected' : ''}" data-website-cape="${escapeAttr(cape.id || '')}"><span class="website-cape-image">${preview}</span><strong>${escapeHtml(cape.name)}</strong><small>${escapeHtml(selected ? 'Aktiv' : (cape.description || 'Auswählen'))}</small></button>`; }).join(''); grid.querySelectorAll('[data-website-cape]').forEach(button => button.onclick = () => selectWebsiteCape(button.dataset.websiteCape || null)); $('websiteCapeNote').textContent = current ? 'Auswahl gespeichert. Starte Minecraft neu, damit das Cape geladen wird.' : 'Wähle dein freigeschaltetes Cape oder entferne die Auswahl.'; }
async function openWebsiteCapeLogin() { const button = $('websiteCapeLoginBtn'); if (button) { button.disabled = true; button.textContent = 'Öffnet …'; } const result = await window.vortex.openCommunityLogin(); if (!result?.ok) { addLog(result?.error || 'Website-Anmeldung konnte nicht geöffnet werden.', 'error'); } else { $('websiteCapeNote').textContent = 'Melde dich im Website-Fenster an. Nach der Rückkehr wird dein Cape geladen.'; } if (button) { button.disabled = false; button.textContent = 'Auf Website anmelden'; } }
async function selectWebsiteCape(capeId) { const result = await window.vortex.selectWebsiteCape(capeId); if (!result.ok) { $('websiteCapeNote').textContent = result.error || 'Cape konnte nicht gespeichert werden.'; addLog(result.error || 'Cape konnte nicht gespeichert werden.', 'error'); return; } $('websiteCapeNote').textContent = result.choice.cape ? `Cape sicher gespeichert und für ${result.written} Instanz(en) vorbereitet. Starte Minecraft neu.` : 'Website-Cape entfernt.'; addLog(result.choice.cape ? `Website-Cape ausgewählt: ${result.choice.cape}.` : 'Website-Cape entfernt.', 'success'); await renderWebsiteCapes(); }
function showCosmeticsTab(tab) { document.querySelectorAll('.cosmetics-tab').forEach(button => button.classList.toggle('active', button.dataset.cosmeticTab === tab)); document.querySelectorAll('.cosmetic-subpage').forEach(page => page.classList.toggle('active', page.id === `cosmetic-${tab}`)); if (tab === 'skins') void updateSkinPreview(); if (tab === 'capes') void renderWebsiteCapes(); }
async function updateSkinPreview() { const result = await window.vortex.getCosmeticSkinPreview(launcherState?.cosmeticsVersion); const image = $('skinPreviewImage'); const label = $('skinPreviewLabel'); if (result?.preview) { image.src = result.preview; image.classList.add('skin-pixel-preview'); label.textContent = `Aktive Vortex-Variante: ${result.fileName}`; } else { image.src = '../assets/branding/vortex-logo.png'; image.classList.remove('skin-pixel-preview'); label.textContent = 'Noch keine Vortex-Skin-Variante erstellt.'; } }
async function createCosmeticSkin() { const button = $('createCosmeticsBtn'); button.disabled = true; button.textContent = 'Skin wählen …'; const result = await window.vortex.importCosmeticSkin(launcherState.cosmeticsVersion, { hat: selectedHat, emblem: selectedEmblem }); if (result.ok) { $('skinManagerStatus').textContent = `Erstellt: ${result.profile.generatedSkin}`; addLog(`Cosmetic-Skin erstellt: ${result.profile.generatedSkin}`, 'success'); await refresh(); await updateSkinPreview(); } else if (!result.canceled) { $('skinManagerStatus').textContent = result.error || 'Skin-Variante konnte nicht erstellt werden.'; addLog(result.error || 'Skin-Variante konnte nicht erstellt werden.', 'error'); } button.disabled = false; button.textContent = 'Skin-Datei wählen'; }
async function createCosmeticSkinByUsername() { const input = $('skinUsername'); const username = input.value.trim(); if (!username) { $('skinManagerStatus').textContent = 'Gib zuerst einen Minecraft-Benutzernamen ein.'; return; } const button = $('importUsernameSkinBtn'); button.disabled = true; button.textContent = 'Lädt …'; const result = await window.vortex.importCosmeticSkinByUsername(launcherState.cosmeticsVersion, username, { hat: selectedHat, emblem: selectedEmblem }); if (result.ok) { $('skinManagerStatus').textContent = `Skin von ${result.username} erstellt: ${result.profile.generatedSkin}`; addLog(`Skin von ${result.username} importiert.`, 'success'); await refresh(); await updateSkinPreview(); } else { $('skinManagerStatus').textContent = result.error || 'Skin konnte nicht geladen werden.'; addLog(result.error || 'Skin konnte nicht geladen werden.', 'error'); } button.disabled = false; button.textContent = 'Skin laden'; }

